func TestParseHookEvent_ConversationIDFallback(t *testing.T) {
	t.Parallel()

	ag := &CursorAgent{}

	t.Run("uses conversation_id", func(t *testing.T) {
		t.Parallel()
		input := `{"conversation_id": "bingo-id", "transcript_path": "/tmp/t.jsonl"}`

