		},
		{
			hookName:       HookNameBeforeSubmitPrompt,
			conversationID: "sess-2",
			input:          `{"conversation_id": "sess-2", "transcript_path": "` + hookProvidedPath + `", "prompt": "hi"}`,
		},
		{
			hookName:       HookNameStop,
			conversationID: "sess-3",
			input:          `{"conversation_id": "sess-3", "transcript_path": "` + hookProvidedPath + `"}`,
		},
		{
			hookName:       HookNameSessionEnd,
			conversationID: "sess-4",
			input:          `{"conversation_id": "sess-4", "transcript_path": "` + hookProvidedPath + `"}`,
		},
		{
			hookName:       HookNamePreCompact,
			conversationID: "sess-5",
			input:          `{"conversation_id": "sess-5", "transcript_path": "` + hookProvidedPath + `"}`,
		},
		{
			hookName:       HookNameSubagentStart,
			conversationID: "sess-6",
			input:          `{"conversation_id": "sess-6", "transcript_path": "` + hookProvidedPath + `", "subagent_id": "s1", "task": "do it"}`,
		},
		{
			hookName:       HookNameSubagentStop,
			conversationID: "sess-7",
			input:          `{"conversation_id": "sess-7", "transcript_path": "` + hookProvidedPath + `", "subagent_id": "s2", "task": "done"}`,
		},
	}

	ag := &CursorAgent{}
	for _, tc := range testCases {
		t.Run(tc.hookName, func(t *testing.T) {
			event, err := ag.ParseHookEvent(tc.hookName, strings.NewReader(tc.input))
			if err != nil {
